    @inline(__always)
    private func checkMultiplyingWhereConstantA(_ value: Lane) {
        let mismatches = Mismatches("multiplyingWhere with a repeating \(hex(value))")
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0xB2B3_D9A3_A296_6570)
        let bInputs = Inputs.vectors(H.self, seed: 0xB2B3_DBA3_A296_68D6)
        mismatches.check(
            H.repeating(value),
            H(raw: HighwayReference.repeatingI8(value)),
            "repeating"
        )
        for (mask, b) in everyPair(maskInputs, bInputs) {
            mismatches.check(
                H.multiplying(H.repeating(value), b, where: mask),
                H(
                    raw: HighwayReference.multiplyingWhereI8(
                        mask.raw,
                        H.repeating(value).raw,
                        b.raw
                    )
                ),
                "mask: \(describe(mask)), b: \(describe(b))"
            )
        }
        mismatches.record()
    }

